-- ************************************** Product.Inventory
CREATE TABLE Product.Inventory
(
InventoryID int64 NOT NULL OPTIONS(description = 'A unique identifier for each inventory record in the table. This primary key ensures that each inventory entry is distinct and can be referenced individually'),
ProductID   int64 OPTIONS(description = 'A reference to the unique identifier of the product associated with the inventory record. This foreign key links to the Product table, allowing the company to associate inventory levels with specific products and track stock availability for each item.'),
Quantity    int64 OPTIONS(description = 'The number of units of the product currently in inventory. This field represents the stock level for each product, helping the company manage inventory levels, reorder supplies, and fulfill customer orders efficiently.'),
PRIMARY KEY (InventoryID) NOT ENFORCED
)
OPTIONS(description = 'Stock of products available for sale.');

